use super::{save, text};
use anyhow::{Result, ensure};
use serde_json::Value;
use std::{
    collections::{HashMap, HashSet},
    fmt::Write,
    fs,
    path::Path,
};

pub(super) fn cypher(data: &Value) -> Result<String> {
    let escaped = |s: &str| s.replace('\\', "\\\\").replace('\'', "\\'");
    let mut lines = vec![
        "// Generated by code-review-graph".to_owned(),
        "// Import: paste into Neo4j Browser or run via cypher-shell".into(),
        String::new(),
    ];
    for n in data["nodes"].as_array().unwrap() {
        let mut fields = vec![];
        for k in ["qualified_name", "name", "file_path", "language"] {
            fields.push(format!("{k}: '{}'", escaped(text(n, k))));
        }
        if let Some(cid) = n["community_id"].as_i64() {
            fields.push(format!("community_id: {cid}"));
        }
        let kind = text(n, "kind");
        ensure!(identifier(kind), "invalid node kind in graph");
        lines.push(format!("CREATE (:{kind} {{{}}});", fields.join(", ")));
    }
    lines.push(String::new());
    for e in data["edges"].as_array().unwrap() {
        let (a, b, kind) = (
            escaped(text(e, "source")),
            escaped(text(e, "target")),
            text(e, "kind"),
        );
        ensure!(identifier(kind), "invalid edge kind in graph");
        lines.push(format!("MATCH (a {{qualified_name: '{a}'}}), (b {{qualified_name: '{b}'}}) CREATE (a)-[:{kind}]->(b);"));
    }
    Ok(lines.join("\n"))
}

fn identifier(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c == '_' || c.is_ascii_alphanumeric())
}

fn slug(s: &str) -> String {
    let mut name = String::new();
    let mut space = false;
    for ch in s.chars().flat_map(char::to_lowercase) {
        if ch.is_whitespace() || ch == '_' {
            space = true;
        } else if ch == '-' || ch.is_alphanumeric() {
            if space && !name.is_empty() {
                name.push('-');
            }
            space = false;
            name.push(ch);
        }
    }
    let name: String = name.trim_matches('-').chars().take(100).collect();
    if name.is_empty() {
        "unnamed".into()
    } else {
        name
    }
}

fn title(s: &str) -> String {
    let mut boundary = true;
    let mut label = String::new();
    for ch in s.replace('-', " ").chars() {
        if boundary {
            label.extend(ch.to_uppercase());
        } else {
            label.extend(ch.to_lowercase());
        }
        boundary = !ch.is_alphabetic();
    }
    label
}

pub(super) fn obsidian(dir: &Path, data: &Value) -> Result<()> {
    ensure!(!dir.is_symlink(), "refusing to export through a symlink");
    fs::create_dir_all(dir)?;
    let nodes = data["nodes"].as_array().unwrap();
    let edges = data["edges"].as_array().unwrap();
    let communities = data["communities"].as_array().unwrap();
    let mut slugs = HashMap::new();
    let mut taken = HashSet::new();
    let mut next = HashMap::new();
    let mut members: HashMap<i64, Vec<&str>> = HashMap::new();
    for n in nodes {
        let qn = text(n, "qualified_name");
        let base = slug(text(n, "name"));
        let counter = next.entry(base.clone()).or_insert(1u32);
        let mut unique = base.clone();
        while !taken.insert(unique.clone()) {
            unique = format!("{base}-{counter}");
            *counter += 1;
        }
        slugs.insert(qn, unique);
        if let Some(cid) = n["community_id"].as_i64() {
            members.entry(cid).or_default().push(qn);
        }
    }
    let mut links: HashMap<&str, Vec<(&str, &str)>> = HashMap::new();
    for e in edges {
        let (a, b, k) = (text(e, "source"), text(e, "target"), text(e, "kind"));
        links.entry(a).or_default().push((b, k));
        links.entry(b).or_default().push((a, k));
    }
    for n in nodes {
        let qn = text(n, "qualified_name");
        let kind = text(n, "kind");
        let file = text(n, "file_path");
        let mut page = String::from("---\n");
        for (key, v) in [
            ("kind", kind),
            ("file", file),
            ("language", text(n, "language")),
        ] {
            writeln!(page, "{key}: {}", serde_json::to_string(v)?)?;
        }
        if let Some(cid) = n["community_id"].as_i64() {
            writeln!(page, "community: {cid}")?;
        }
        write!(
            page,
            "tags:\n  - {}\n---\n# {}\n\n**Kind:** {kind}\n**File:** `{file}`\n",
            serde_json::to_string(&kind.to_lowercase())?,
            text(n, "name")
        )?;
        if let Some(neighbors) = links.get(qn) {
            page.push_str("\n## Connections\n");
            let mut seen = HashSet::new();
            for (target, k) in neighbors {
                if let Some(slug) = slugs.get(target)
                    && seen.insert(slug)
                {
                    write!(page, "\n- {k}: [[{slug}|{}]]", title(slug))?;
                }
            }
        }
        save(&dir.join(format!("{}.md", slugs[qn])), page.as_bytes())?;
    }
    for c in communities {
        let id = c["id"].as_i64().unwrap();
        let mut lines = vec![
            format!("# Community: {}", text(c, "name")),
            String::new(),
            format!("**Size:** {}", c["size"]),
            format!("**Cohesion:** {:.2}", c["cohesion"].as_f64().unwrap_or(0.)),
        ];
        let lang = text(c, "dominant_language");
        if !lang.is_empty() {
            lines.push(format!("**Language:** {lang}"));
        }
        lines.extend(["".into(), "## Members".into(), "".into()]);
        for name in members.get(&id).into_iter().flatten().take(50) {
            if let Some(slug) = slugs.get(name) {
                lines.push(format!("- [[{slug}]]"));
            }
        }
        save(
            &dir.join(format!("_COMMUNITY_{id}.md")),
            lines.join("\n").as_bytes(),
        )?;
    }
    let mut listing = nodes.iter().collect::<Vec<_>>();
    listing.sort_by_key(|n| text(n, "name"));
    let mut lines = vec![
        "# Code Graph Index".into(),
        String::new(),
        format!("**Nodes:** {}", nodes.len()),
        format!("**Edges:** {}", edges.len()),
        format!("**Communities:** {}", communities.len()),
        String::new(),
        "## All Nodes".into(),
        String::new(),
    ];
    for n in listing {
        lines.push(format!(
            "- [[{}]] ({})",
            slugs[text(n, "qualified_name")],
            text(n, "kind")
        ));
    }
    save(&dir.join("_INDEX.md"), lines.join("\n").as_bytes())?;
    eprintln!(
        "INFO: Obsidian vault exported to {} ({} pages)",
        dir.display(),
        nodes.len()
    );
    println!("Obsidian vault exported: {}", dir.display());
    Ok(())
}
